import math

class SFTTransitionSimulator:
    def __init__(self):
        # Simulated logit distributions for Base vs SFT models
        # Target tokens: 'Paris' (Direct answer), 'What' (Quiz continuation)
        self.base_logits = {"Paris": 1.2, "What": 3.8, "The": 2.1}
        self.sft_logits  = {"Paris": 4.5, "What": 0.2, "The": 1.1}

    def compute_probs(self, logits: dict) -> dict:
        max_l = max(logits.values())
        exp_vals = {k: math.exp(v - max_l) for k, v in logits.items()}
        sum_exp = sum(exp_vals.values())
        return {k: v / sum_exp for k, v in exp_vals.items()}

    def cross_entropy(self, probs: dict, target: str) -> float:
        return -math.log(max(probs.get(target, 1e-12), 1e-12))

sim = SFTTransitionSimulator()
base_probs = sim.compute_probs(sim.base_logits)
sft_probs  = sim.compute_probs(sim.sft_logits)

target = "Paris"
loss_base = sim.cross_entropy(base_probs, target)
loss_sft  = sim.cross_entropy(sft_probs, target)

print("=== BASE TO INSTRUCTION SFT SIMULATION ===")
print(f"Target Token:        '{target}'")
print(f"Base Model P(Paris): {base_probs['Paris']:.4f} | SFT Loss: {loss_base:.4f}")
print(f"SFT Model P(Paris):  {sft_probs['Paris']:.4f} | SFT Loss: {loss_sft:.4f}")
print("-" * 55)
assert sft_probs['Paris'] > 0.85
assert loss_sft < 0.20
print("Assertion Passed: SFT successfully shifts probability mass onto instruction target!")

